import sys, heapq

def main():
    data = sys.stdin.read().split()
    q = int(data[0])
    lo, hi = [], []   # lo: max-heap of the smaller half (negated), hi: min-heap of the larger half
    out = []
    p = 1
    push, pop, pushpop = heapq.heappush, heapq.heappop, heapq.heappushpop
    for _ in range(q):
        op = data[p]
        if op == 'add':
            x = int(data[p + 1])
            p += 2
            if lo and x > -lo[0]:
                x = pushpop(hi, x)
            push(lo, -x)
            if len(lo) > len(hi) + 1:
                push(hi, -pop(lo))
        else:
            p += 1
            if len(lo) > len(hi):
                out.append(-2 * lo[0])
            else:
                out.append(hi[0] - lo[0])
    sys.stdout.write('\n'.join(map(str, out)) + '\n')

main()

